/**
*@filelibavformatmuxingAPIusageexample
*@examplemux.c
*
*Generateasyntheticaudioandvideosignalandmuxthemtoamediafilein
*anysupportedlibavformatformat.Thedefaultcodecsareused.
*/

#include<stdlib.h>
#include<stdio.h>
#include<string.h>
#include<math.h>

#include<libavutil/avassert.h>
#include<libavutil/channel_layout.h>
#include<libavutil/opt.h>
#include<libavutil/mathematics.h>
#include<libavutil/timestamp.h>
#include<libavcodec/avcodec.h>
#include<libavformat/avformat.h>
#include<libswscale/swscale.h>
#include<libswresample/swresample.h>

#defineSTREAM_DURATION10.0
#defineSTREAM_FRAME_RATE25/*25images/s*/
#defineSTREAM_PIX_FMTAV_PIX_FMT_YUV420P/*defaultpix_fmt*/

#defineSCALE_FLAGSSWS_BICUBIC

//awrapperaroundasingleoutputAVStream
typedefstructOutputStream{
AVStream*st;
AVCodecContext*enc;

/*ptsofthenextframethatwillbegenerated*/
int64_tnext_pts;
intsamples_count;

AVFrame*frame;
AVFrame*tmp_frame;

AVPacket*tmp_pkt;

floatt,tincr,tincr2;

structSwsContext*sws_ctx;
structSwrContext*swr_ctx;
}OutputStream;

staticvoidlog_packet(constAVFormatContext*fmt_ctx,constAVPacket*pkt)
{
AVRational*time_base=&fmt_ctx->streams[pkt->stream_index]->time_base;

printf("pts:%spts_time:%sdts:%sdts_time:%sduration:%sduration_time:%sstream_index:%d\n",
av_ts2str(pkt->pts),av_ts2timestr(pkt->pts,time_base),
av_ts2str(pkt->dts),av_ts2timestr(pkt->dts,time_base),
av_ts2str(pkt->duration),av_ts2timestr(pkt->duration,time_base),
pkt->stream_index);
}

staticintwrite_frame(AVFormatContext*fmt_ctx,AVCodecContext*c,
AVStream*st,AVFrame*frame,AVPacket*pkt)
{
intret;

//sendtheframetotheencoder
ret=avcodec_send_frame(c,frame);
if(ret<0){
fprintf(stderr,"Errorsendingaframetotheencoder:%s\n",
av_err2str(ret));
exit(1);
}

while(ret>=0){
ret=avcodec_receive_packet(c,pkt);
if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF)
break;
elseif(ret<0){
fprintf(stderr,"Errorencodingaframe:%s\n",av_err2str(ret));
exit(1);
}

/*rescaleoutputpackettimestampvaluesfromcodectostreamtimebase*/
av_packet_rescale_ts(pkt,c->time_base,st->time_base);
pkt->stream_index=st->index;

/*Writethecompressedframetothemediafile.*/
log_packet(fmt_ctx,pkt);
ret=av_interleaved_write_frame(fmt_ctx,pkt);
/*pktisnowblank(av_interleaved_write_frame()takesownershipof
*itscontentsandresetspkt),sothatnounreferencingisnecessary.
*Thiswouldbedifferentifoneusedav_write_frame().*/
if(ret<0){
fprintf(stderr,"Errorwhilewritingoutputpacket:%s\n",av_err2str(ret));
exit(1);
}
}

returnret==AVERROR_EOF?1:0;
}

/*Addanoutputstream.*/
staticvoidadd_stream(OutputStream*ost,AVFormatContext*oc,
constAVCodec**codec,
enumAVCodecIDcodec_id)
{
AVCodecContext*c;
inti;

/*findtheencoder*/
*codec=avcodec_find_encoder(codec_id);
if(!(*codec)){
fprintf(stderr,"Couldnotfindencoderfor'%s'\n",
avcodec_get_name(codec_id));
exit(1);
}

ost->tmp_pkt=av_packet_alloc();
if(!ost->tmp_pkt){
fprintf(stderr,"CouldnotallocateAVPacket\n");
exit(1);
}

ost->st=avformat_new_stream(oc,NULL);
if(!ost->st){
fprintf(stderr,"Couldnotallocatestream\n");
exit(1);
}
ost->st->id=oc->nb_streams-1;
c=avcodec_alloc_context3(*codec);
if(!c){
fprintf(stderr,"Couldnotallocanencodingcontext\n");
exit(1);
}
ost->enc=c;

switch((*codec)->type){
caseAVMEDIA_TYPE_AUDIO:
c->sample_fmt=(*codec)->sample_fmts?
(*codec)->sample_fmts[0]:AV_SAMPLE_FMT_FLTP;
c->bit_rate=64000;
c->sample_rate=44100;
if((*codec)->supported_samplerates){
c->sample_rate=(*codec)->supported_samplerates[0];
for(i=0;(*codec)->supported_samplerates[i];i++){
if((*codec)->supported_samplerates[i]==44100)
c->sample_rate=44100;
}
}
av_channel_layout_copy(&c->ch_layout,&(AVChannelLayout)AV_CHANNEL_LAYOUT_STEREO);
ost->st->time_base=(AVRational){1,c->sample_rate};
break;

caseAVMEDIA_TYPE_VIDEO:
c->codec_id=codec_id;

c->bit_rate=400000;
/*Resolutionmustbeamultipleoftwo.*/
c->width=352;
c->height=288;
/*timebase:Thisisthefundamentalunitoftime(inseconds)interms
*ofwhichframetimestampsarerepresented.Forfixed-fpscontent,
*timebaseshouldbe1/framerateandtimestampincrementsshouldbe
*identicalto1.*/
ost->st->time_base=(AVRational){1,STREAM_FRAME_RATE};
c->time_base=ost->st->time_base;

c->gop_size=12;/*emitoneintraframeeverytwelveframesatmost*/
c->pix_fmt=STREAM_PIX_FMT;
if(c->codec_id==AV_CODEC_ID_MPEG2VIDEO){
/*justfortesting,wealsoaddB-frames*/
c->max_b_frames=2;
}
if(c->codec_id==AV_CODEC_ID_MPEG1VIDEO){
/*Neededtoavoidusingmacroblocksinwhichsomecoeffsoverflow.
*Thisdoesnothappenwithnormalvideo,itjusthappenshereas
*themotionofthechromaplanedoesnotmatchthelumaplane.*/
c->mb_decision=2;
}
break;

default:
break;
}

/*Someformatswantstreamheaderstobeseparate.*/
if(oc->oformat->flags&AVFMT_GLOBALHEADER)
c->flags|=AV_CODEC_FLAG_GLOBAL_HEADER;
}

/**************************************************************/
/*audiooutput*/

staticAVFrame*alloc_audio_frame(enumAVSampleFormatsample_fmt,
constAVChannelLayout*channel_layout,
intsample_rate,intnb_samples)
{
AVFrame*frame=av_frame_alloc();
if(!frame){
fprintf(stderr,"Errorallocatinganaudioframe\n");
exit(1);
}

frame->format=sample_fmt;
av_channel_layout_copy(&frame->ch_layout,channel_layout);
frame->sample_rate=sample_rate;
frame->nb_samples=nb_samples;

if(nb_samples){
if(av_frame_get_buffer(frame,0)<0){
fprintf(stderr,"Errorallocatinganaudiobuffer\n");
exit(1);
}
}

returnframe;
}

staticvoidopen_audio(AVFormatContext*oc,constAVCodec*codec,
OutputStream*ost,AVDictionary*opt_arg)
{
AVCodecContext*c;
intnb_samples;
intret;
AVDictionary*opt=NULL;

c=ost->enc;

/*openit*/
av_dict_copy(&opt,opt_arg,0);
ret=avcodec_open2(c,codec,&opt);
av_dict_free(&opt);
if(ret<0){
fprintf(stderr,"Couldnotopenaudiocodec:%s\n",av_err2str(ret));
exit(1);
}

/*initsignalgenerator*/
ost->t=0;
ost->tincr=2*M_PI*110.0/c->sample_rate;
/*incrementfrequencyby110Hzpersecond*/
ost->tincr2=2*M_PI*110.0/c->sample_rate/c->sample_rate;

if(c->codec->capabilities&AV_CODEC_CAP_VARIABLE_FRAME_SIZE)
nb_samples=10000;
else
nb_samples=c->frame_size;

ost->frame=alloc_audio_frame(c->sample_fmt,&c->ch_layout,
c->sample_rate,nb_samples);
ost->tmp_frame=alloc_audio_frame(AV_SAMPLE_FMT_S16,&c->ch_layout,
c->sample_rate,nb_samples);

/*copythestreamparameterstothemuxer*/
ret=avcodec_parameters_from_context(ost->st->codecpar,c);
if(ret<0){
fprintf(stderr,"Couldnotcopythestreamparameters\n");
exit(1);
}

/*createresamplercontext*/
ost->swr_ctx=swr_alloc();
if(!ost->swr_ctx){
fprintf(stderr,"Couldnotallocateresamplercontext\n");
exit(1);
}

/*setoptions*/
av_opt_set_chlayout(ost->swr_ctx,"in_chlayout",&c->ch_layout,0);
av_opt_set_int(ost->swr_ctx,"in_sample_rate",c->sample_rate,0);
av_opt_set_sample_fmt(ost->swr_ctx,"in_sample_fmt",AV_SAMPLE_FMT_S16,0);
av_opt_set_chlayout(ost->swr_ctx,"out_chlayout",&c->ch_layout,0);
av_opt_set_int(ost->swr_ctx,"out_sample_rate",c->sample_rate,0);
av_opt_set_sample_fmt(ost->swr_ctx,"out_sample_fmt",c->sample_fmt,0);

/*initializetheresamplingcontext*/
if((ret=swr_init(ost->swr_ctx))<0){
fprintf(stderr,"Failedtoinitializetheresamplingcontext\n");
exit(1);
}
}

/*Preparea16bitdummyaudioframeof'frame_size'samplesand
*'nb_channels'channels.*/
staticAVFrame*get_audio_frame(OutputStream*ost)
{
AVFrame*frame=ost->tmp_frame;
intj,i,v;
int16_t*q=(int16_t*)frame->data[0];

/*checkifwewanttogeneratemoreframes*/
if(av_compare_ts(ost->next_pts,ost->enc->time_base,
STREAM_DURATION,(AVRational){1,1})>0)
returnNULL;

for(j=0;j<frame->nb_samples;j++){
v=(int)(sin(ost->t)*10000);
for(i=0;i<ost->enc->ch_layout.nb_channels;i++)
*q++=v;
ost->t+=ost->tincr;
ost->tincr+=ost->tincr2;
}

frame->pts=ost->next_pts;
ost->next_pts+=frame->nb_samples;

returnframe;
}

/*
*encodeoneaudioframeandsendittothemuxer
*return1whenencodingisfinished,0otherwise
*/
staticintwrite_audio_frame(AVFormatContext*oc,OutputStream*ost)
{
AVCodecContext*c;
AVFrame*frame;
intret;
intdst_nb_samples;

c=ost->enc;

frame=get_audio_frame(ost);

if(frame){
/*convertsamplesfromnativeformattodestinationcodecformat,usingtheresampler*/
/*computedestinationnumberofsamples*/
dst_nb_samples=swr_get_delay(ost->swr_ctx,c->sample_rate)+frame->nb_samples;
av_assert0(dst_nb_samples==frame->nb_samples);

/*whenwepassaframetotheencoder,itmaykeepareferencetoit
*internally;
*makesurewedonotoverwriteithere
*/
ret=av_frame_make_writable(ost->frame);
if(ret<0)
exit(1);

/*converttodestinationformat*/
ret=swr_convert(ost->swr_ctx,
ost->frame->data,dst_nb_samples,
(constuint8_t**)frame->data,frame->nb_samples);
if(ret<0){
fprintf(stderr,"Errorwhileconverting\n");
exit(1);
}
frame=ost->frame;

frame->pts=av_rescale_q(ost->samples_count,(AVRational){1,c->sample_rate},c->time_base);
ost->samples_count+=dst_nb_samples;
}

returnwrite_frame(oc,c,ost->st,frame,ost->tmp_pkt);
}

/**************************************************************/
/*videooutput*/

staticAVFrame*alloc_frame(enumAVPixelFormatpix_fmt,intwidth,intheight)
{
AVFrame*frame;
intret;

frame=av_frame_alloc();
if(!frame)
returnNULL;

frame->format=pix_fmt;
frame->width=width;
frame->height=height;

/*allocatethebuffersfortheframedata*/
ret=av_frame_get_buffer(frame,0);
if(ret<0){
fprintf(stderr,"Couldnotallocateframedata.\n");
exit(1);
}

returnframe;
}

staticvoidopen_video(AVFormatContext*oc,constAVCodec*codec,
OutputStream*ost,AVDictionary*opt_arg)
{
intret;
AVCodecContext*c=ost->enc;
AVDictionary*opt=NULL;

av_dict_copy(&opt,opt_arg,0);

/*openthecodec*/
ret=avcodec_open2(c,codec,&opt);
av_dict_free(&opt);
if(ret<0){
fprintf(stderr,"Couldnotopenvideocodec:%s\n",av_err2str(ret));
exit(1);
}

/*allocateandinitare-usableframe*/
ost->frame=alloc_frame(c->pix_fmt,c->width,c->height);
if(!ost->frame){
fprintf(stderr,"Couldnotallocatevideoframe\n");
exit(1);
}

/*IftheoutputformatisnotYUV420P,thenatemporaryYUV420P
*pictureisneededtoo.Itisthenconvertedtotherequired
*outputformat.*/
ost->tmp_frame=NULL;
if(c->pix_fmt!=AV_PIX_FMT_YUV420P){
ost->tmp_frame=alloc_frame(AV_PIX_FMT_YUV420P,c->width,c->height);
if(!ost->tmp_frame){
fprintf(stderr,"Couldnotallocatetemporaryvideoframe\n");
exit(1);
}
}

/*copythestreamparameterstothemuxer*/
ret=avcodec_parameters_from_context(ost->st->codecpar,c);
if(ret<0){
fprintf(stderr,"Couldnotcopythestreamparameters\n");
exit(1);
}
}

/*Prepareadummyimage.*/
staticvoidfill_yuv_image(AVFrame*pict,intframe_index,
intwidth,intheight)
{
intx,y,i;

i=frame_index;

/*Y*/
for(y=0;y<height;y++)
for(x=0;x<width;x++)
pict->data[0][y*pict->linesize[0]+x]=x+y+i*3;

/*CbandCr*/
for(y=0;y<height/2;y++){
for(x=0;x<width/2;x++){
pict->data[1][y*pict->linesize[1]+x]=128+y+i*2;
pict->data[2][y*pict->linesize[2]+x]=64+x+i*5;
}
}
}

staticAVFrame*get_video_frame(OutputStream*ost)
{
AVCodecContext*c=ost->enc;

/*checkifwewanttogeneratemoreframes*/
if(av_compare_ts(ost->next_pts,c->time_base,
STREAM_DURATION,(AVRational){1,1})>0)
returnNULL;

/*whenwepassaframetotheencoder,itmaykeepareferencetoit
*internally;makesurewedonotoverwriteithere*/
if(av_frame_make_writable(ost->frame)<0)
exit(1);

if(c->pix_fmt!=AV_PIX_FMT_YUV420P){
/*asweonlygenerateaYUV420Ppicture,wemustconvertit
*tothecodecpixelformatifneeded*/
if(!ost->sws_ctx){
ost->sws_ctx=sws_getContext(c->width,c->height,
AV_PIX_FMT_YUV420P,
c->width,c->height,
c->pix_fmt,
SCALE_FLAGS,NULL,NULL,NULL);
if(!ost->sws_ctx){
fprintf(stderr,
"Couldnotinitializetheconversioncontext\n");
exit(1);
}
}
fill_yuv_image(ost->tmp_frame,ost->next_pts,c->width,c->height);
sws_scale(ost->sws_ctx,(constuint8_t*const*)ost->tmp_frame->data,
ost->tmp_frame->linesize,0,c->height,ost->frame->data,
ost->frame->linesize);
}else{
fill_yuv_image(ost->frame,ost->next_pts,c->width,c->height);
}

ost->frame->pts=ost->next_pts++;

returnost->frame;
}

/*
*encodeonevideoframeandsendittothemuxer
*return1whenencodingisfinished,0otherwise
*/
staticintwrite_video_frame(AVFormatContext*oc,OutputStream*ost)
{
returnwrite_frame(oc,ost->enc,ost->st,get_video_frame(ost),ost->tmp_pkt);
}

staticvoidclose_stream(AVFormatContext*oc,OutputStream*ost)
{
avcodec_free_context(&ost->enc);
av_frame_free(&ost->frame);
av_frame_free(&ost->tmp_frame);
av_packet_free(&ost->tmp_pkt);
sws_freeContext(ost->sws_ctx);
swr_free(&ost->swr_ctx);
}

/**************************************************************/
/*mediafileoutput*/

intmain(intargc,char**argv)
{
OutputStreamvideo_st={0},audio_st={0};
constAVOutputFormat*fmt;
constchar*filename;
AVFormatContext*oc;
constAVCodec*audio_codec,*video_codec;
intret;
inthave_video=0,have_audio=0;
intencode_video=0,encode_audio=0;
AVDictionary*opt=NULL;
inti;

if(argc<2){
printf("usage:%soutput_file\n"
"APIexampleprogramtooutputamediafilewithlibavformat.\n"
"Thisprogramgeneratesasyntheticaudioandvideostream,encodesand\n"
"muxesthemintoafilenamedoutput_file.\n"
"Theoutputformatisautomaticallyguessedaccordingtothefileextension.\n"
"Rawimagescanalsobeoutputbyusing'%%d'inthefilename.\n"
"\n",argv[0]);
return1;
}

filename=argv[1];
for(i=2;i+1<argc;i+=2){
if(!strcmp(argv[i],"-flags")||!strcmp(argv[i],"-fflags"))
av_dict_set(&opt,argv[i]+1,argv[i+1],0);
}

/*allocatetheoutputmediacontext*/
avformat_alloc_output_context2(&oc,NULL,NULL,filename);
if(!oc){
printf("Couldnotdeduceoutputformatfromfileextension:usingMPEG.\n");
avformat_alloc_output_context2(&oc,NULL,"mpeg",filename);
}
if(!oc)
return1;

fmt=oc->oformat;

/*Addtheaudioandvideostreamsusingthedefaultformatcodecs
*andinitializethecodecs.*/
if(fmt->video_codec!=AV_CODEC_ID_NONE){
add_stream(&video_st,oc,&video_codec,fmt->video_codec);
have_video=1;
encode_video=1;
}
if(fmt->audio_codec!=AV_CODEC_ID_NONE){
add_stream(&audio_st,oc,&audio_codec,fmt->audio_codec);
have_audio=1;
encode_audio=1;
}

/*Nowthatalltheparametersareset,wecanopentheaudioand
*videocodecsandallocatethenecessaryencodebuffers.*/
if(have_video)
open_video(oc,video_codec,&video_st,opt);

if(have_audio)
open_audio(oc,audio_codec,&audio_st,opt);

av_dump_format(oc,0,filename,1);

/*opentheoutputfile,ifneeded*/
if(!(fmt->flags&AVFMT_NOFILE)){
ret=avio_open(&oc->pb,filename,AVIO_FLAG_WRITE);
if(ret<0){
fprintf(stderr,"Couldnotopen'%s':%s\n",filename,
av_err2str(ret));
return1;
}
}

/*Writethestreamheader,ifany.*/
ret=avformat_write_header(oc,&opt);
if(ret<0){
fprintf(stderr,"Erroroccurredwhenopeningoutputfile:%s\n",
av_err2str(ret));
return1;
}

while(encode_video||encode_audio){
/*selectthestreamtoencode*/
if(encode_video&&
(!encode_audio||av_compare_ts(video_st.next_pts,video_st.enc->time_base,
audio_st.next_pts,audio_st.enc->time_base)<=0)){
encode_video=!write_video_frame(oc,&video_st);
}else{
encode_audio=!write_audio_frame(oc,&audio_st);
}
}

av_write_trailer(oc);

/*Closeeachcodec.*/
if(have_video)
close_stream(oc,&video_st);
if(have_audio)
close_stream(oc,&audio_st);

if(!(fmt->flags&AVFMT_NOFILE))
/*Closetheoutputfile.*/
avio_closep(&oc->pb);

/*freethestream*/
avformat_free_context(oc);

return0;
}
